BEGIN;
DO $test$
DECLARE ceo uuid:='b8cbf27e-2391-4fb5-b061-f1488e8c3135'; manager uuid; w uuid; source uuid; q public.quality_reviews; q2 public.quality_reviews; token uuid:=gen_random_uuid(); report jsonb; next_job uuid; total integer;
BEGIN
 PERFORM set_config('request.jwt.claim.sub',ceo::text,true);
 SELECT id INTO manager FROM public.agents WHERE code='CPO' AND is_active;
 w:=public.create_work_order('QUALITY ROLLBACK FIXTURE','提交一句测试文本','只能一句话',manager,gen_random_uuid());
 SELECT (result->>'current_job_id')::uuid INTO source FROM public.tasks WHERE id=w;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=source;
 PERFORM public.complete_chat_reply(source,token,'第一句。第二句。','[]');
 SELECT * INTO q FROM public.quality_reviews WHERE work_order_id=w AND source_job_id=source;
 IF q.id IS NULL OR q.employee_id::text=(SELECT input->>'employee_id' FROM public.tasks WHERE id=w) THEN RAISE EXCEPTION 'Missing independent inspector';END IF;
 IF public.request_text_quality(w,source)<>q.id OR (SELECT count(*) FROM public.quality_reviews WHERE source_job_id=source)<>1 THEN RAISE EXCEPTION 'Duplicate inspection';END IF;
 BEGIN PERFORM public.review_work_order(w,source,'accept','Bypass');RAISE EXCEPTION 'Unreviewed delivery accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 report:='{"verdict":"revise","summary":"只允许一句话，当前两句，请改为一句。","checks":[{"id":"task_goal","status":"pass","evidence":"第一句。","reason":"有文本"},{"id":"task_acceptance","status":"fail","evidence":"第一句。第二句。","reason":"有两个句号，不是一句话"},{"id":"truthfulness","status":"pass","evidence":"第一句。","reason":"没有虚构外部操作"}]}';
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q.job_id;
 BEGIN PERFORM public.complete_chat_reply(q.job_id,gen_random_uuid(),report::text,'[]');RAISE EXCEPTION 'Stale inspector lease allowed';EXCEPTION WHEN serialization_failure THEN NULL;END;
 PERFORM public.fail_chat_reply(q.job_id,token,'synthetic_fault',false,'[]');
 PERFORM public.request_text_quality(w,source);
 IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=q.job_id AND execution_state='queued' AND attempt_count=1) THEN RAISE EXCEPTION 'Explicit retry lost attempt history';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=2,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q.job_id;
 PERFORM public.complete_chat_reply(q.job_id,token,report::text,'[]');
 SELECT (result->>'current_job_id')::uuid INTO next_job FROM public.tasks WHERE id=w;
 IF next_job=source OR (SELECT input->>'quality_rework_count' FROM public.tasks WHERE id=w)<>'1' OR (SELECT jsonb_array_length(input->'runs') FROM public.tasks WHERE id=w)<>2 THEN RAISE EXCEPTION 'Internal repair not queued once';END IF;
 PERFORM public.complete_chat_reply(q.job_id,token,report::text,'[]');
 IF (SELECT jsonb_array_length(input->'runs') FROM public.tasks WHERE id=w)<>2 THEN RAISE EXCEPTION 'Completion retry duplicated repair';END IF;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=next_job;
 PERFORM public.complete_chat_reply(next_job,token,'仍然两句。依旧错误。','[]');
 SELECT * INTO q2 FROM public.quality_reviews WHERE source_job_id=next_job;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q2.job_id;
 report:=replace(replace(report::text,'第一句','仍然两句'),'第二句','依旧错误')::jsonb;
 PERFORM public.complete_chat_reply(q2.job_id,token,report::text,'[]');
 IF (SELECT jsonb_array_length(input->'runs') FROM public.tasks WHERE id=w)<>2 THEN RAISE EXCEPTION 'Unbounded automatic repair';END IF;
 BEGIN PERFORM public.review_work_order(w,next_job,'accept','Quality failed');RAISE EXCEPTION 'Failed inspection accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.review_work_order(w,next_job,'revise','CEO要求再改一次，只提交：测试。');
 SELECT (result->>'current_job_id')::uuid INTO next_job FROM public.tasks WHERE id=w;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=next_job;
 PERFORM public.complete_chat_reply(next_job,token,'测试。','[]');
 SELECT * INTO q2 FROM public.quality_reviews WHERE source_job_id=next_job;
 report:='{"verdict":"pass","summary":"一句测试文本，等待CEO验收","checks":[{"id":"task_goal","status":"pass","evidence":"测试。","reason":"有目标文本"},{"id":"task_acceptance","status":"pass","evidence":"测试。","reason":"只有一句"},{"id":"truthfulness","status":"pass","evidence":"测试。","reason":"无虚构操作"}]}';
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q2.job_id;
 BEGIN PERFORM public.complete_chat_reply(q2.job_id,token,replace(report::text,'测试。','伪造证据。'),'[]');RAISE EXCEPTION 'False evidence allowed';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.complete_chat_reply(q2.job_id,token,report::text,'[]');
 IF (SELECT result->>'review_state' FROM public.tasks WHERE id=w)='accepted' THEN RAISE EXCEPTION 'Quality performed CEO acceptance';END IF;
 PERFORM public.review_work_order(w,next_job,'accept','Synthetic final acceptance');
 IF NOT EXISTS(SELECT 1 FROM public.company_knowledge WHERE source_task_id=w AND source_job_id=next_job) THEN RAISE EXCEPTION 'Knowledge archive regression';END IF;
 w:=public.create_work_order('QUALITY HUMAN ROLLBACK FIXTURE','文本中的运行结论待核实','真实运行应人工核查',manager,gen_random_uuid());
 SELECT (result->>'current_job_id')::uuid INTO source FROM public.tasks WHERE id=w;
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=source;
 PERFORM public.complete_chat_reply(source,token,'运行情况需要人工核查。','[]');
 SELECT * INTO q FROM public.quality_reviews WHERE source_job_id=source;
 report:='{"verdict":"needs_human","summary":"缺少真实运行证据","checks":[{"id":"task_goal","status":"not_checked","evidence":"","reason":"需人工核查"},{"id":"task_acceptance","status":"not_checked","evidence":"","reason":"需真实运行证据"},{"id":"truthfulness","status":"not_checked","evidence":"","reason":"无足够证据"}]}';
 UPDATE public.tasks SET execution_state='running',attempt_count=1,lease_token=token,lease_expires_at=now()+interval '90 seconds' WHERE id=q.job_id;
 PERFORM public.complete_chat_reply(q.job_id,token,report::text,'[]');
 BEGIN PERFORM public.review_work_order(w,source,'accept','');RAISE EXCEPTION 'Uncertain output accepted without evidence';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.review_work_order(w,source,'accept','回滚测试人工证据：已实际检查指定流程，确认满足本次标准，此为合成测试记录。');
 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 BEGIN PERFORM public.request_text_quality(w,source);RAISE EXCEPTION 'Foreign actor allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_table_privilege('authenticated','public.quality_reviews','UPDATE') OR has_function_privilege('authenticated','private.queue_text_quality(uuid)','EXECUTE') OR has_function_privilege('anon','public.request_text_quality(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Excess inspection privileges';END IF;
END $test$;
SET LOCAL ROLE authenticated;
DO $rls$ BEGIN IF EXISTS(SELECT 1 FROM public.quality_reviews) THEN RAISE EXCEPTION 'Cross-tenant quality leak';END IF;END $rls$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: automatic independent inspections, immutable source versions, lease/idempotency, bounded internal repair, acceptance gate, evidence validation, CEO-only acceptance, knowledge archive and RLS; fixtures rolled back' AS checks;
